  function activeData(name){return state.editing&&state.editing.mode==="release"&&state.releaseDetail?(state.releaseDetail.data[name]||[]):(state.data[name]||[])}
  function parameterOptions(optional,includeOutputs){var html=optional?'<option value="">无（使用常数）</option>':'';if(includeOutputs)html+='<option value="__predicted_price_wan">预测价格</option><option value="__capability_score">效能分</option><option value="__feasibility_probability">可行概率</option>';return html+activeData("parameters").map(function(p){return'<option value="'+esc(p.parameter_id)+'">'+esc(p.label)+' ['+esc(p.parameter_id)+']</option>'}).join('')}
