  function wireReleaseHeader(){q("createReleaseBtn").onclick=createRelease;q("cloneCurrentReleaseBtn").onclick=cloneCurrentRelease;q("releasePackageFile").onchange=function(){state.releasePackageFile=this.files[0]||null;q("importReleasePackageBtn").disabled=!state.releasePackageFile||state.readOnly};q("importReleasePackageBtn").onclick=importReleasePackage;q("historyProductFile").onchange=function(){state.historyFile=this.files[0]||null;state.historyPreview=null;q("createHistoryReleaseBtn").disabled=true;q("historyInferenceReport").innerHTML=""};q("previewHistoryBtn").onclick=previewHistoricalProducts;q("createHistoryReleaseBtn").onclick=createHistoricalRelease;q("releaseSelector").onchange=async function(){state.releaseId=this.value||null;state.releaseDetail=null;state.releasePreview=null;await renderProductReleases()}}
