  async function previewHistoricalProducts(){if(!state.historyFile)return toast("请先选择历史成品 CSV/XLSX");var payload=historyPayload();if(!payload.product_code||!payload.product_name)return toast("请填写新成品代号和名称");try{payload.file_base64=await fileToBase64(state.historyFile);state.historyPreview=await api("/api/admin/product-releases/history/preview",{method:"POST",body:JSON.stringify(payload)});q("historyInferenceReport").innerHTML=historyInferenceHtml(state.historyPreview);q("createHistoryReleaseBtn").disabled=state.readOnly;toast("自动推断完成；请重点确认标红的0/1或全缺失字段",7000)}catch(e){toast("历史成品分析失败："+e.message,10000)}}
