  function releaseModuleHtml(editable){var section=state.releaseSection,c=configs[section],rows=state.releaseDetail.data[section]||[];var template='<a class="button secondary" href="/api/admin/product-releases/module/template?release_id='+encodeURIComponent(state.releaseId)+'&section='+encodeURIComponent(section)+'">下载本模块CSV模板</a>';var importBox=editable?'<div class="release-import-box"><label class="upload-box">选择 '+esc(c.title)+' CSV/XLSX 文件<input id="releaseModuleFile" type="file" accept=".csv,.xlsx"></label><label><input id="releaseSkipInvalid" type="checkbox"> 暂存时跳过格式错误行</label><button id="previewReleaseFileBtn" class="button secondary">解析预览</button><button id="stageReleaseFileBtn" class="button primary" disabled>暂存到草稿</button></div><div id="releaseImportReport"></div>':'';var add=editable?'<button id="addReleaseRow" class="button primary">＋ 界面新增</button>':'';return'<div class="admin-toolbar"><h2>'+esc(c.title)+'（'+rows.length+'）</h2><div class="release-toolbar-actions">'+template+add+'</div></div><p class="admin-lifecycle-note">可直接在界面逐条维护，也可上传独立CSV/XLSX覆盖本模块。暂存不会修改当前运行数据库。</p>'+importBox+'<div class="admin-table-wrap"><table class="admin-table"><thead><tr>'+c.columns.map(function(x){return'<th>'+esc(x[1])+'</th>'}).join('')+(editable?'<th>草稿操作</th>':'')+'</tr></thead><tbody>'+rows.map(function(row,index){return'<tr>'+c.columns.map(function(x){var value=row[x[0]];if(typeof value==="object")value=JSON.stringify(value);return'<td>'+esc(enumText(x[0],value))+'</td>'}).join('')+(editable?'<td><div class="row-actions"><button class="release-edit" data-index="'+index+'">编辑</button><button class="release-delete danger" data-index="'+index+'">删除</button></div></td>':'')+'</tr>'}).join('')+'</tbody></table></div>'}
  function wireReleaseModule(editable){Array.prototype.forEach.call(document.querySelectorAll("[data-release-section]"),function(button){button.onclick=function(){state.releaseSection=button.dataset.releaseSection;state.releasePreview=null;renderProductReleases()}});if(!editable)return;q("addReleaseRow").onclick=function(){openReleaseEdit(state.releaseSection,{},null)};Array.prototype.forEach.call(document.querySelectorAll(".release-edit"),function(button){button.onclick=function(){var index=Number(button.dataset.index);openReleaseEdit(state.releaseSection,state.releaseDetail.data[state.releaseSection][index],index)}});Array.prototype.forEach.call(document.querySelectorAll(".release-delete"),function(button){button.onclick=async function(){var index=Number(button.dataset.index),items=(state.releaseDetail.data[state.releaseSection]||[]).slice();if(!confirm("仅从当前草稿删除该记录，是否继续？"))return;items.splice(index,1);await saveReleaseSection(items);toast("已从草稿删除")}});q("releaseModuleFile").onchange=function(){state.releaseFile=this.files[0]||null;state.releasePreview=null;q("stageReleaseFileBtn").disabled=true;q("releaseImportReport").innerHTML=""};q("previewReleaseFileBtn").onclick=previewReleaseFile;q("stageReleaseFileBtn").onclick=stageReleaseFile}
  async function createRelease(){if(state.readOnly)return;var code=q("releaseProductCode").value.trim(),name=q("releaseProductName").value.trim();if(!code||!name)return toast("请填写成品代号和名称");try{var result=await api("/api/admin/product-releases/create",{method:"POST",body:JSON.stringify({product_code:code,product_name:name,seed_schema:false})});state.releaseId=result.release_id;state.releaseDetail=result;state.releaseSection="parameters";await load();toast("空白业务草稿已创建；不会读取当前HTTP模型字段")}catch(e){toast("创建失败："+e.message,9000)}}
