  function releaseImportHtml(report){if(!report)return"";return'<div class="import-summary"><div><span>总行数</span><b>'+report.row_count+'</b></div><div><span>格式有效</span><b class="status-good">'+report.valid_count+'</b></div><div><span>格式错误</span><b class="'+(report.invalid_count?'status-bad':'status-good')+'">'+report.invalid_count+'</b></div></div>'+((report.global_warnings||[]).map(function(x){return'<p>提醒：'+esc(x)+'</p>'}).join(''))+(report.rows||[]).filter(function(x){return !x.valid}).slice(0,30).map(function(x){return'<p class="status-bad">第 '+x.row_number+' 行：'+esc((x.errors||[]).join("；"))+'</p>'}).join('')}
