  function releaseValidationHtml(report){if(!report)return'<div class="generation-report">业务数据可直接切换；这里的检查是可选的，只检查表内编号、类型和引用，不检查HTTP模型。</div>';return'<div class="generation-report '+(report.valid?'success':'')+'"><b>'+(report.valid?'业务数据结构可写入':'业务数据存在结构问题')+'</b></div>'+((report.errors||[]).length?'<div class="datamaster-errors">'+report.errors.map(function(x){return'<p>× '+esc(x)+'</p>'}).join('')+'</div>':'')+((report.warnings||[]).length?'<div class="datamaster-warnings">'+report.warnings.map(function(x){return'<p>! '+esc(x)+'</p>'}).join('')+'</div>':'')}
